// Pi abe508e1b89912adde45528136c3221eb69acdd7 (MIT): differential cases for PiSharp.Durable's internal ports of packages/ai/src/utils
// (overflow.ts, retry.ts, transcript.ts, estimate.ts, uuid.ts). There is no upstream test file: Fixtures/piai-utils.upstream.json holds what
// the pinned pi-ai returns under Node for every input below (generated by running these functions from packages/ai/src with
// `node --conditions=source --experimental-strip-types`), and the cases compare the ports with it. Where PiSharp already ports a function
// outside PiSharp.Durable's references (PiSharp.CodingAgent's SessionRecoveryClassifier and AgentRetryPolicy, PiSharp.AI's internal
// ProviderTranscript.CurrentTools), a second case compares the two ports on the same inputs.
using System.Reflection;
using System.Text.RegularExpressions;
using PiSharp.CodingAgent;
using PiSharp.CodingAgent.Configuration;
using PiSharp.Contracts;
using PiSharp.Durable.Chord;
using JsonArray = System.Text.Json.Nodes.JsonArray;
using JsonNode = System.Text.Json.Nodes.JsonNode;
using PiSharp.Durable.Internal.PiAi;
using static SessionTests;

internal static partial class Program
{
    private static IEnumerable<(string, Func<Task>)> PiAiUtilsCases() => PiAiUtilsTests.Cases("piai.");
}

/// <summary>The piai.* differential cases.</summary>
internal static class PiAiUtilsTests
{
    private static readonly Lazy<JsonObjectValue> Upstream = new(() => (JsonObjectValue)JsonValue.Parse(
        File.ReadAllText(Path.Combine(Program.RepositoryRoot(), "tests", "PiSharp.Durable.Tests", "Fixtures", "piai-utils.upstream.json"))));

    private static IEnumerable<JsonObjectValue> Rows(string key) => ((JsonArrayValue)Upstream.Value[key]).Cast<JsonObjectValue>();

    private static bool Bool(JsonValue value) => ((JsonBooleanValue)value).Value;

    private static double? Window(JsonValue value) => value switch
    {
        JsonNumberValue number => number.Value,
        JsonStringValue { Value: "NaN" } => double.NaN,
        _ => null,
    };

    internal static IEnumerable<(string, Func<Task>)> Cases(string prefix)
    {
        yield return Program.Case(prefix + "overflow.matches-upstream", () =>
        {
            var count = 0;
            foreach (var row in Rows("overflow"))
            {
                var message = (JsonObjectValue)row["message"];
                Program.Equal(Bool(row["result"]), PiAiOverflow.IsContextOverflow(message, Window(row["contextWindow"])), $"isContextOverflow({row.ToJson()})");
                count++;
            }
            Program.Check(count > 100, "overflow rows");
        });

        yield return Program.Case(prefix + "overflow.matches-codingagent-session-recovery-classifier", () =>
        {
            foreach (var row in Rows("overflow"))
            {
                var message = (JsonObjectValue)row["message"];
                var native = PiWireJson.ReadMessage(message.ToData().Value);
                var window = Window(row["contextWindow"]);
                Program.Equal(SessionRecoveryClassifier.IsContextOverflow(native, window), PiAiOverflow.IsContextOverflow(message, window),
                    $"isContextOverflow({row.ToJson()})");
            }
        });

        yield return Program.Case(prefix + "retry.matches-upstream", () =>
        {
            foreach (var row in Rows("retry"))
                Program.Equal(Bool(row["result"]), PiAiRetry.IsRetryableAssistantError((JsonObjectValue)row["message"]), $"isRetryableAssistantError({row.ToJson()})");
        });

        yield return Program.Case(prefix + "retry.matches-codingagent-agent-retry-policy", () =>
        {
            foreach (var row in Rows("retry"))
            {
                var message = (JsonObjectValue)row["message"];
                var stopReason = PiWireJson.ReadStopReason(S(message["stopReason"]));
                var error = message.TryGetValue("errorMessage", out var text) ? S(text) : null;
                Program.Equal(AgentRetryPolicy.IsRetryableError(stopReason, error), PiAiRetry.IsRetryableAssistantError(message),
                    $"isRetryableAssistantError({row.ToJson()})");
            }
        });

        yield return Program.Case(prefix + "retry-delay.matches-upstream", () =>
        {
            foreach (var row in Rows("delays"))
            {
                var max = row["maxAgentDelayMs"] is JsonNumberValue number ? number.Value : (double?)null;
                Program.Equal(N(row["result"]), PiAiRetry.RetryDelayMs(N(row["baseDelayMs"]), max, (int)N(row["attempt"])), $"retryDelayMs({row.ToJson()})");
            }
        });

        yield return Program.Case(prefix + "retry-delay.matches-codingagent-agent-retry-policy", () =>
        {
            var compared = 0;
            foreach (var row in Rows("delays"))
            {
                var baseDelay = N(row["baseDelayMs"]);
                // AgentRetryPolicy takes whole-millisecond delays up to the largest safe integer.
                if (Math.Truncate(baseDelay) != baseDelay || baseDelay > AgentRetryPolicy.MaximumSafeInteger) continue;
                var max = row["maxAgentDelayMs"] is JsonNumberValue number ? number.Value : PiAiRetry.DefaultMaxAgentRetryDelayMs;
                var attempt = (int)N(row["attempt"]);
                var policy = new AgentRetryPolicy(true, 3, (long)baseDelay, (long)max);
                Program.Equal((double)policy.DelayMs(attempt), PiAiRetry.RetryDelayMs(baseDelay, max, attempt), $"delay({row.ToJson()})");
                compared++;
            }
            Program.Check(compared > 40, "compared delays");
        });

        yield return Program.Case(prefix + "transcript.current-tools-match-upstream", () =>
        {
            foreach (var row in Rows("transcripts"))
            {
                var actual = PiAiTranscript.GetCurrentTools((JsonArrayValue)row["messages"]);
                Program.Equal(row["result"].ToJson(), JsonValue.Array(actual).ToJson(), "getCurrentTools");
            }
        });

        yield return Program.Case(prefix + "transcript.current-tools-match-pisharp-ai-provider-transcript", () =>
        {
            // ProviderTranscript is internal to PiSharp.AI, which grants internals only to PiSharp.CodingAgent.
            var type = typeof(PiSharp.AI.AssistantStreamReducer).Assembly.GetType("PiSharp.AI.Protocols.ProviderShared.ProviderTranscript", throwOnError: true)!;
            var currentTools = type.GetMethod("CurrentTools", BindingFlags.Static | BindingFlags.NonPublic | BindingFlags.Public)!;
            foreach (var row in Rows("transcripts"))
            {
                var messages = ((JsonArrayValue)row["messages"]).Select(message => (System.Text.Json.Nodes.JsonObject)JsonNode.Parse(message.ToJson())!).ToList();
                var theirs = (List<System.Text.Json.Nodes.JsonObject>)currentTools.Invoke(null, [messages])!;
                var ours = PiAiTranscript.GetCurrentTools((JsonArrayValue)row["messages"]);
                Program.Equal(JsonValue.Parse(new JsonArray([.. theirs]).ToJsonString()).ToJson(), JsonValue.Array(ours).ToJson(), "CurrentTools");
            }
        });

        yield return Program.Case(prefix + "transcript.declarations-match-upstream", () =>
        {
            foreach (var row in Rows("pairs"))
            {
                var (left, right) = ((JsonObjectValue)row["left"], (JsonObjectValue)row["right"]);
                Program.Equal(Bool(row["result"]), PiAiTranscript.DeclarationsEqual(left, right), $"declarationsEqual({row.ToJson()})");
                Program.Equal(row["declaration"].ToJson(), PiAiTranscript.ToToolDeclaration(left).ToJson(), "toToolDeclaration");
            }
        });

        yield return Program.Case(prefix + "estimate.matches-upstream", () =>
        {
            foreach (var row in Rows("estimates"))
                Program.Equal(N(row["result"]), PiAiEstimate.EstimateMessageTokens(row["message"]), $"estimateMessageTokens({row.ToJson()})");
            foreach (var row in Rows("contextTokens"))
                Program.Equal(N(row["result"]), PiAiEstimate.CalculateContextTokens((JsonObjectValue)row["usage"]), $"calculateContextTokens({row.ToJson()})");
        });

        yield return Program.Case(prefix + "uuid.is-a-version-7-uuid-like-upstream", () =>
        {
            // Upstream's value is time-dependent; its shape is pinned: lowercase hyphenated, version 7, variant 10.
            const string shape = "^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$";
            var before = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
            var uuid = PiAiUuid.UuidV7();
            var after = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
            Program.Check(Regex.IsMatch(uuid, shape), $"a UUIDv7: {uuid}");
            var timestamp = Convert.ToInt64(uuid.Replace("-", "", StringComparison.Ordinal)[..12], 16);
            Program.Check(timestamp >= before && timestamp <= after, $"the 48-bit timestamp {timestamp} is now ({before}..{after})");
        });
    }
}
